-- Reset auto-increment serial sequences for PostgreSQL
SELECT setval('stations_station_id_seq', (SELECT COALESCE(MAX(station_id), 1) FROM stations));
SELECT setval('vehicles_vehicle_id_seq', (SELECT COALESCE(MAX(vehicle_id), 1) FROM vehicles));
SELECT setval('drivers_driver_id_seq', (SELECT COALESCE(MAX(driver_id), 1) FROM drivers));
SELECT setval('customers_customer_id_seq', (SELECT COALESCE(MAX(customer_id), 1) FROM customers));
SELECT setval('routes_route_id_seq', (SELECT COALESCE(MAX(route_id), 1) FROM routes));
SELECT setval('trips_trip_id_seq', (SELECT COALESCE(MAX(trip_id), 1) FROM trips));
SELECT setval('bookings_booking_id_seq', (SELECT COALESCE(MAX(booking_id), 1) FROM bookings));
SELECT setval('parcels_parcel_id_seq', (SELECT COALESCE(MAX(parcel_id), 1) FROM parcels));
